parameters.jsCode:
const entrada = $input.first().json;

// Estado salvo anteriormente para esta sessão
const anterior = $('Buscar Estado da Conversa').first().json ?? {};

// Resultado do interpretador
const interpretacao = entrada.output ?? {};

const changes = interpretacao.changes ?? {};

const clearFields = Array.isArray(interpretacao.clear_fields)
  ? interpretacao.clear_fields
  : [];

// ==================================================
// INTENT
// ==================================================

const intent =
  interpretacao.intent ??
  'analytical_query';

// ==================================================
// QUERY SHAPE
// ==================================================

// query_shape NÃO é filtro de negócio.
//
// Ele vem diretamente do Interpretador:
//
// count
// list
// group
// ranking
// comparison
// comparison
//
// Não deve existir dentro de changes ou clear_fields.

const QUERY_SHAPES_VALIDOS = [
  'count',
  'list',
  'group',
  'ranking',
  'comparison',
];

function normalizarQueryShape(valor) {
  if (
    typeof valor !== 'string' ||
    !QUERY_SHAPES_VALIDOS.includes(valor.trim())
  ) {
    return null;
  }

  return valor.trim();
}

// Forma anteriormente salva na conversa.
// Em estados antigos pode não existir.
const queryShapeAnterior =
  normalizarQueryShape(anterior.query_shape);

// Forma definida pela mensagem atual.
let queryShape =
  normalizarQueryShape(
    interpretacao.query_shape
  );

// explain_source e clarification não executam
// consulta estruturada.
if (intent !== 'analytical_query') {
  queryShape = null;
} else {
  // Para consulta analítica, a forma atual
  // informada pelo Interpretador sempre prevalece.
  //
  // Se por compatibilidade alguma execução antiga
  // não trouxer query_shape, reutilizamos o anterior.
  //
  // Se também não existir anterior, usamos list como
  // fallback seguro para estados antigos.

  queryShape =
    queryShape ??
    queryShapeAnterior ??
    'list';
}


// ==================================================
// COMPARISON
// ==================================================

// comparison NÃO é filtro de negócio.
//
// Ele descreve dois itens que serão comparados pelo
// backend determinístico.
//
// A Data Table salva esse objeto como texto JSON.

const COMPARISON_DIMENSIONS_VALIDAS = [
  'period',
  'praca',
  'store_name',
  'location_term',
  'analyst_responsible',
  'supplier',
  'requester',
  'category',
  'subcategory',
  'status',
];

const BREAKDOWN_DIMENSIONS_VALIDAS = [
  'praca',
  'store_name',
  'analyst_responsible',
  'supplier',
  'requester',
  'category',
  'subcategory',
  'status',
];

const BREAKDOWN_ORDERS_VALIDAS = [
  'absolute_change',
  'increase',
  'decrease',
];

function normalizarComparison(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return null;
  }

  let objeto = valor;

  if (typeof valor === 'string') {
    let texto = valor.trim();

    if (texto.startsWith('=')) {
      texto = texto.slice(1).trim();
    }

    try {
      objeto = JSON.parse(texto);
    } catch {
      return null;
    }
  }

  if (
    typeof objeto !== 'object' ||
    Array.isArray(objeto) ||
    objeto === null
  ) {
    return null;
  }

  const dimension =
    typeof objeto.dimension === 'string'
      ? objeto.dimension.trim()
      : null;

  if (
    !dimension ||
    !COMPARISON_DIMENSIONS_VALIDAS.includes(
      dimension
    ) ||
    !Array.isArray(objeto.items) ||
    objeto.items.length !== 2
  ) {
    return null;
  }

  const items = objeto.items.map(item => {
    if (
      typeof item !== 'object' ||
      Array.isArray(item) ||
      item === null
    ) {
      return null;
    }

    const normalizarString = valorItem => {
      if (
        valorItem === null ||
        valorItem === undefined ||
        valorItem === ''
      ) {
        return null;
      }

      return String(valorItem).trim() || null;
    };

    const normalizarInteiro = valorItem => {
      if (
        valorItem === null ||
        valorItem === undefined ||
        valorItem === ''
      ) {
        return null;
      }

      const numero = Number(valorItem);

      return Number.isInteger(numero)
        ? numero
        : null;
    };

    return {
      label:
        normalizarString(item.label),
      value:
        normalizarString(item.value),
      year:
        normalizarInteiro(item.year),
      month:
        normalizarInteiro(item.month),
      start_date:
        normalizarString(item.start_date),
      end_date:
        normalizarString(item.end_date),
    };
  });

  if (items.some(item => item === null)) {
    return null;
  }

  let breakdownBy =
    typeof objeto.breakdown_by === 'string' &&
    BREAKDOWN_DIMENSIONS_VALIDAS.includes(
      objeto.breakdown_by.trim()
    )
      ? objeto.breakdown_by.trim()
      : null;

  let breakdownOrder =
    typeof objeto.breakdown_order === 'string' &&
    BREAKDOWN_ORDERS_VALIDAS.includes(
      objeto.breakdown_order.trim()
    )
      ? objeto.breakdown_order.trim()
      : null;

  let breakdownLimit = null;

  if (
    objeto.breakdown_limit !== null &&
    objeto.breakdown_limit !== undefined &&
    objeto.breakdown_limit !== ''
  ) {
    const numero =
      Number(objeto.breakdown_limit);

    if (
      Number.isInteger(numero) &&
      numero >= 1 &&
      numero <= 100
    ) {
      breakdownLimit = numero;
    }
  }

  const analysisMode =
    objeto.analysis_mode === 'drivers'
      ? 'drivers'
      : null;

  let driverDimensions = null;

  if (Array.isArray(objeto.driver_dimensions)) {
    const dimensoes = [
      ...new Set(
        objeto.driver_dimensions
          .filter(
            campo =>
              typeof campo === 'string' &&
              BREAKDOWN_DIMENSIONS_VALIDAS.includes(
                campo.trim()
              ) &&
              campo.trim() !== dimension
          )
          .map(campo => campo.trim())
      ),
    ].slice(0, 5);

    driverDimensions =
      dimensoes.length > 0
        ? dimensoes
        : null;
  }

  let driverLimit = null;

  if (
    objeto.driver_limit !== null &&
    objeto.driver_limit !== undefined &&
    objeto.driver_limit !== ''
  ) {
    const numero =
      Number(objeto.driver_limit);

    if (
      Number.isInteger(numero) &&
      numero >= 1 &&
      numero <= 10
    ) {
      driverLimit = numero;
    }
  }

  if (analysisMode === 'drivers') {
    // Drivers e breakdown simples são modos alternativos
    // de detalhar a mesma comparação.
    breakdownBy = null;
    breakdownOrder = null;
    breakdownLimit = null;
  } else {
    driverDimensions = null;
    driverLimit = null;

    if (!breakdownBy) {
      breakdownOrder = null;
      breakdownLimit = null;
    } else if (!breakdownOrder) {
      breakdownOrder = 'absolute_change';
    }
  }

  if (breakdownBy === dimension) {
    return null;
  }

  return {
    dimension,
    items,
    breakdown_by: breakdownBy,
    breakdown_order: breakdownOrder,
    breakdown_limit: breakdownLimit,
    analysis_mode: analysisMode,
    driver_dimensions: driverDimensions,
    driver_limit: driverLimit,
  };
}

const comparisonAnterior =
  normalizarComparison(
    anterior.comparison
  );

const comparisonInterpretada =
  normalizarComparison(
    interpretacao.comparison
  );

let comparison = null;

if (
  intent === 'analytical_query' &&
  queryShape === 'comparison'
) {
  comparison =
    comparisonInterpretada ??
    (
      queryShapeAnterior === 'comparison'
        ? comparisonAnterior
        : null
    );
}

// ==================================================
// RESPONSE FORMAT
// ==================================================

// response_format NÃO é filtro de negócio.
//
// Ele controla SOMENTE a apresentação de uma listagem.
//
// Valores:
//
// detailed_list
// table
//
// Para count, group, ranking e comparison:
// response_format = null
//
// Não deve existir dentro de changes ou clear_fields.

const RESPONSE_FORMATS_VALIDOS = [
  'detailed_list',
  'table',
];

function normalizarResponseFormat(valor) {
  if (
    typeof valor !== 'string'
  ) {
    return null;
  }

  const normalizado = valor.trim();

  if (
    !RESPONSE_FORMATS_VALIDOS.includes(normalizado)
  ) {
    return null;
  }

  return normalizado;
}

// Formato salvo anteriormente.
const responseFormatAnterior =
  normalizarResponseFormat(
    anterior.response_format
  );

// Formato definido pela mensagem atual.
const responseFormatInterpretado =
  normalizarResponseFormat(
    interpretacao.response_format
  );

let responseFormat = null;

if (intent !== 'analytical_query') {
  // explain_source e clarification
  // não utilizam formato de listagem.
  responseFormat = null;

} else if (queryShape === 'list') {
  // Para listagem:
  //
  // 1. formato explicitamente interpretado prevalece;
  // 2. se a conversa anterior também era list,
  //    preservamos o formato anterior;
  // 3. fallback padrão = detailed_list.

  const consultaAnteriorEraLista =
    queryShapeAnterior === 'list';

  responseFormat =
    responseFormatInterpretado ??
    (
      consultaAnteriorEraLista
        ? responseFormatAnterior
        : null
    ) ??
    'detailed_list';

} else {
  // count, group e ranking possuem
  // apresentação própria.
  responseFormat = null;
}

// ==================================================
// DISPLAY FIELDS
// ==================================================

const DISPLAY_FIELDS_VALIDOS = [
  'praca',
  'analyst_responsible',
  'supplier',
  'requester',
  'completion_date',
  'visit_date',
];

function normalizarDisplayFields(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return null;
  }

  let lista = valor;

  // A Data Table salva como texto JSON.
  if (typeof valor === 'string') {
    let texto = valor.trim();

    if (texto.startsWith('=')) {
      texto = texto.slice(1).trim();
    }

    try {
      const parsed = JSON.parse(texto);

      if (Array.isArray(parsed)) {
        lista = parsed;
      } else {
        return null;
      }
    } catch {
      return null;
    }
  }

  if (!Array.isArray(lista)) {
    return null;
  }

  return [
    ...new Set(
      lista
        .filter(
          campo =>
            typeof campo === 'string' &&
            DISPLAY_FIELDS_VALIDOS.includes(
              campo.trim()
            )
        )
        .map(campo => campo.trim())
    ),
  ];
}

// Campos extras anteriormente salvos.
const displayFieldsAnterior =
  normalizarDisplayFields(
    anterior.display_fields
  );

// Campo devolvido pelo Interpretador.
// [] é válido e significa "nenhum campo extra".
let displayFields;

if (Array.isArray(interpretacao.display_fields)) {
  displayFields =
    normalizarDisplayFields(
      interpretacao.display_fields
    ) ?? [];
} else {
  displayFields =
    displayFieldsAnterior ?? [];
}

// explain_source e clarification não utilizam
// configuração de apresentação.
if (intent !== 'analytical_query') {
  displayFields = null;
}

// ==================================================
// STATUS VÁLIDOS
// ==================================================

const STATUS_VALIDOS = [
  'Em Aberto',
  'Em atendimento',
  'Pendente de aprovação',
  'Não Aprovado',
  'Concluído',
];

// Converte:
// - array real
// - JSON salvo como string
// - status único legado
//
// sempre para:
//
// ["Status 1", "Status 2"]
//
// ou null.

function normalizarStatuses(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return null;
  }

  let lista = valor;

  // --------------------------------------------------
  // TRATAMENTO DE STRING
  // --------------------------------------------------

  if (typeof valor === 'string') {
    let texto = valor.trim();

    // Compatibilidade com registros que foram
    // salvos incorretamente como:
    //
    // =["Em atendimento"]
    //
    // em vez de:
    //
    // ["Em atendimento"]

    if (texto.startsWith('=')) {
      texto = texto.slice(1).trim();
    }

    try {
      const parsed = JSON.parse(texto);

      if (Array.isArray(parsed)) {
        lista = parsed;
      } else if (typeof parsed === 'string') {
        lista = [parsed];
      } else {
        lista = [texto];
      }
    } catch {
      // Compatibilidade com status único legado:
      //
      // "Em atendimento"

      lista = [texto];
    }
  }

  if (!Array.isArray(lista)) {
    lista = [lista];
  }

  const normalizados = [
    ...new Set(
      lista
        .filter(
          status =>
            typeof status === 'string' &&
            STATUS_VALIDOS.includes(status.trim())
        )
        .map(status => status.trim())
    ),
  ];

  return normalizados.length > 0
    ? normalizados
    : null;
}

// ==================================================
// MULTI FILTERS E SELEÇÃO CONTEXTUAL
// ==================================================

const MULTI_FILTER_DIMENSIONS_VALIDAS = [
  'praca',
  'store_name',
  'location_term',
  'analyst_responsible',
  'supplier',
  'requester',
  'category',
  'subcategory',
];

const SELECTION_MODES_VALIDOS = [
  'comparison_items',
  'top_drivers',
  'offsets',
  'breakdown',
];

function parseObjetoJson(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return null;
  }

  if (
    typeof valor === 'object' &&
    !Array.isArray(valor)
  ) {
    return valor;
  }

  if (typeof valor !== 'string') {
    return null;
  }

  let texto = valor.trim();

  if (texto.startsWith('=')) {
    texto = texto.slice(1).trim();
  }

  try {
    const parsed = JSON.parse(texto);

    return (
      parsed &&
      typeof parsed === 'object' &&
      !Array.isArray(parsed)
    )
      ? parsed
      : null;
  } catch {
    return null;
  }
}

function normalizarListaTextual(valor, preservarVazio = false) {
  if (!Array.isArray(valor)) {
    return null;
  }

  const vistos = new Set();
  const lista = [];

  for (const item of valor) {
    if (typeof item !== 'string') {
      continue;
    }

    const texto = item.trim();

    if (!texto) {
      continue;
    }

    const chave = texto.toLocaleLowerCase('pt-BR');

    if (vistos.has(chave)) {
      continue;
    }

    vistos.add(chave);
    lista.push(texto);
  }

  if (lista.length > 0) {
    return lista.slice(0, 100);
  }

  return preservarVazio
    ? []
    : null;
}

function normalizarMultiFilters(valor, preservarVazios = false) {
  const objeto = parseObjetoJson(valor);

  if (!objeto) {
    return null;
  }

  const resultado = {};

  for (const dimension of MULTI_FILTER_DIMENSIONS_VALIDAS) {
    if (!Object.prototype.hasOwnProperty.call(objeto, dimension)) {
      continue;
    }

    const lista = normalizarListaTextual(
      objeto[dimension],
      preservarVazios
    );

    if (lista !== null) {
      resultado[dimension] = lista;
    }
  }

  return Object.keys(resultado).length > 0
    ? resultado
    : null;
}

function normalizarSelectionInstrucao(valor) {
  const objeto = parseObjetoJson(valor);

  if (!objeto) {
    return null;
  }

  const source =
    objeto.source === 'previous_comparison'
      ? 'previous_comparison'
      : null;

  const mode =
    typeof objeto.mode === 'string' &&
    SELECTION_MODES_VALIDOS.includes(objeto.mode.trim())
      ? objeto.mode.trim()
      : null;

  const dimension =
    typeof objeto.dimension === 'string' &&
    BREAKDOWN_DIMENSIONS_VALIDAS.includes(objeto.dimension.trim())
      ? objeto.dimension.trim()
      : null;

  let limit = null;

  if (
    objeto.limit !== null &&
    objeto.limit !== undefined &&
    objeto.limit !== ''
  ) {
    const numero = Number(objeto.limit);

    if (
      Number.isInteger(numero) &&
      numero >= 1 &&
      numero <= 100
    ) {
      limit = numero;
    }
  }

  if (!source || !mode || !dimension) {
    return null;
  }

  return {
    source,
    mode,
    dimension,
    limit,
  };
}

function normalizarSelectionPersistida(valor) {
  const objeto = parseObjetoJson(valor);

  if (!objeto) {
    return null;
  }

  const instrucao = normalizarSelectionInstrucao(objeto);
  const sourceComparison = normalizarComparison(
    objeto.source_comparison
  );
  const sourceState = parseObjetoJson(
    objeto.source_state
  );

  if (
    !instrucao ||
    !sourceComparison ||
    !sourceState
  ) {
    return null;
  }

  return {
    ...instrucao,
    source_state: sourceState,
    source_comparison: sourceComparison,
  };
}

// ==================================================
// CAMPOS PERSISTENTES DO ESTADO
// ==================================================

// query_shape NÃO entra aqui.
//
// response_format NÃO entra aqui.
//
// display_fields NÃO entra aqui.
//
// Eles são tratados separadamente porque representam
// estrutura e apresentação da consulta, e não filtros
// de negócio.

const camposEstado = [
  'event',
  'date_field',
  'year',
  'month',
  'start_date',
  'end_date',

  'praca',
  'store_name',
  'location_term',

  // status antigo mantido temporariamente
  // para compatibilidade
  'status',

  // novo campo canônico
  'statuses',

  'analyst_responsible',
  'supplier',
  'requester',
  'category',
  'subcategory',

  'group_by',
  'limit',

  'missing_field',
];

// ==================================================
// RECUPERA ESTADO ANTERIOR
// ==================================================

const estado = {};

for (const campo of camposEstado) {
  if (campo === 'statuses') {
    continue;
  }

  estado[campo] = anterior[campo] ?? null;
}

// `statuses` pode vir da Data Table
// armazenado como JSON em texto.
estado.statuses = normalizarStatuses(
  anterior.statuses
);

// Filtros múltiplos são persistidos como JSON em texto.
estado.multi_filters =
  normalizarMultiFilters(
    anterior.multi_filters
  );

// ==================================================
// COMPATIBILIDADE COM ESTADOS ANTIGOS
// ==================================================

// Conversas criadas antes da existência de `statuses`
// podem possuir apenas:
//
// status = "Em atendimento"
//
// Se a consulta anterior era de situação atual,
// convertemos silenciosamente para:
//
// statuses = ["Em atendimento"]

if (
  !estado.statuses &&
  anterior.event === 'current_status' &&
  typeof anterior.status === 'string' &&
  STATUS_VALIDOS.includes(anterior.status)
) {
  estado.statuses = [anterior.status];
}

// Snapshot do estado anterior usado para reconstruir
// seleções contextuais originadas da comparação anterior.
const estadoAnteriorParaSelecao =
  JSON.parse(JSON.stringify(estado));

// ==================================================
// APLICA ALTERAÇÕES EXPLÍCITAS
// ==================================================

// multi_filters é um objeto parcial: cada dimensão
// informada altera somente aquela parte do filtro.
const multiFiltersChanges =
  normalizarMultiFilters(
    changes.multi_filters,
    true
  );

if (multiFiltersChanges) {
  const atuais = {
    ...(estado.multi_filters ?? {}),
  };

  for (const [dimension, valores] of Object.entries(multiFiltersChanges)) {
    if (!Array.isArray(valores)) {
      continue;
    }

    if (valores.length === 0) {
      delete atuais[dimension];
      continue;
    }

    atuais[dimension] = valores;

    // O múltiplo substitui o singular da MESMA dimensão.
    if (Object.prototype.hasOwnProperty.call(estado, dimension)) {
      estado[dimension] = null;
    }
  }

  estado.multi_filters =
    Object.keys(atuais).length > 0
      ? atuais
      : null;
}

for (const [campo, valor] of Object.entries(changes)) {
  if (!camposEstado.includes(campo)) {
    continue;
  }

  // null em changes NÃO apaga estado.
  // Para apagar, utilizar clear_fields.

  if (
    valor === null ||
    valor === undefined
  ) {
    continue;
  }

  // Novo campo de múltiplos status
  if (campo === 'statuses') {
    const statusesNormalizados =
      normalizarStatuses(valor);

    if (statusesNormalizados) {
      estado.statuses =
        statusesNormalizados;

      // Sempre que a nova estrutura for utilizada,
      // removemos o status legado.
      estado.status = null;
    }

    continue;
  }

  // Um filtro singular explícito substitui eventual
  // filtro múltiplo da mesma dimensão.
  if (
    MULTI_FILTER_DIMENSIONS_VALIDAS.includes(campo) &&
    estado.multi_filters &&
    Object.prototype.hasOwnProperty.call(
      estado.multi_filters,
      campo
    )
  ) {
    delete estado.multi_filters[campo];

    if (Object.keys(estado.multi_filters).length === 0) {
      estado.multi_filters = null;
    }
  }

  estado[campo] = valor;
}

// ==================================================
// COMPATIBILIDADE COM `status` ANTIGO
// ==================================================

// O novo Interpretador não deve mais gerar
// changes.status.
//
// Porém, se alguma execução antiga/fallback ainda
// produzir status único, não quebramos a conversa.

if (
  Object.prototype.hasOwnProperty.call(
    changes,
    'status'
  ) &&
  typeof changes.status === 'string' &&
  STATUS_VALIDOS.includes(changes.status) &&
  !Object.prototype.hasOwnProperty.call(
    changes,
    'statuses'
  )
) {
  estado.status = changes.status;
  estado.statuses = [changes.status];
}

// ==================================================
// REMOVE FILTROS EXPLICITAMENTE SOLICITADOS
// ==================================================

for (const campo of clearFields) {
  if (!camposEstado.includes(campo)) {
    continue;
  }

  // Proteção adicional:
  //
  // se, por erro do LLM, um campo aparecer
  // simultaneamente em changes e clear_fields,
  // o valor explicitamente alterado em changes
  // tem prioridade.

  const possuiAlteracaoExplicita =
    Object.prototype.hasOwnProperty.call(
      changes,
      campo
    ) &&
    changes[campo] !== null &&
    changes[campo] !== undefined;

  if (possuiAlteracaoExplicita) {
    continue;
  }

  estado[campo] = null;

  // Se statuses for removido,
  // também eliminamos eventual status legado.
  if (campo === 'statuses') {
    estado.status = null;
  }
}

// ==================================================
// REGRA DE MIGRAÇÃO
// ==================================================

// Sempre que o Interpretador utilizar statuses,
// status deixa definitivamente de participar
// daquela consulta.

if (
  Object.prototype.hasOwnProperty.call(
    changes,
    'statuses'
  ) &&
  estado.statuses
) {
  estado.status = null;
}

// ==================================================
// COERÊNCIA ENTRE EVENTO, CAMPO TEMPORAL E STATUS
// ==================================================

if (
  Object.prototype.hasOwnProperty.call(
    changes,
    'event'
  )
) {
  // -----------------------------------------------
  // CHAMADOS ABERTOS / CRIADOS
  // -----------------------------------------------

  if (changes.event === 'opened') {
    estado.date_field = 'created_on';

    // Evento histórico simples não deve herdar
    // filtro de status atual anterior.
    //
    // Uma consulta combinada/coorte deve utilizar
    // event = current_status com date_field.

    const possuiStatusAtualExplicito =
      Object.prototype.hasOwnProperty.call(
        changes,
        'statuses'
      ) ||
      Object.prototype.hasOwnProperty.call(
        changes,
        'status'
      );

    if (!possuiStatusAtualExplicito) {
      estado.statuses = null;
      estado.status = null;
    }
  }

  // -----------------------------------------------
  // CHAMADOS CONCLUÍDOS
  // -----------------------------------------------

  if (changes.event === 'completed') {
    estado.date_field = 'completion_date';

    const possuiStatusAtualExplicito =
      Object.prototype.hasOwnProperty.call(
        changes,
        'statuses'
      ) ||
      Object.prototype.hasOwnProperty.call(
        changes,
        'status'
      );

    if (!possuiStatusAtualExplicito) {
      estado.statuses = null;
      estado.status = null;
    }
  }

  // -----------------------------------------------
  // VISITAS
  // -----------------------------------------------

  if (changes.event === 'visited') {
    estado.date_field = 'visit_date';

    const possuiStatusAtualExplicito =
      Object.prototype.hasOwnProperty.call(
        changes,
        'statuses'
      ) ||
      Object.prototype.hasOwnProperty.call(
        changes,
        'status'
      );

    if (!possuiStatusAtualExplicito) {
      estado.statuses = null;
      estado.status = null;
    }
  }

  // -----------------------------------------------
  // SITUAÇÃO ATUAL
  // -----------------------------------------------

  if (changes.event === 'current_status') {
    // Verifica se a própria mensagem atual definiu
    // explicitamente uma coorte histórica.
    //
    // Exemplo:
    //
    // "Dos chamados criados em agosto,
    // quais ainda estão em atendimento?"

    const periodoHistoricoExplicito =
      Object.prototype.hasOwnProperty.call(
        changes,
        'date_field'
      ) ||
      Object.prototype.hasOwnProperty.call(
        changes,
        'year'
      ) ||
      Object.prototype.hasOwnProperty.call(
        changes,
        'month'
      ) ||
      Object.prototype.hasOwnProperty.call(
        changes,
        'start_date'
      ) ||
      Object.prototype.hasOwnProperty.call(
        changes,
        'end_date'
      );

    // Situação puramente atual:
    //
    // não herdar período histórico antigo.

    if (!periodoHistoricoExplicito) {
      estado.date_field = null;
      estado.year = null;
      estado.month = null;
      estado.start_date = null;
      estado.end_date = null;
    }
  }
}

// ==================================================
// SEGURANÇA EXTRA — statuses REPRESENTA STATUS ATUAL
// ==================================================

// Se o Interpretador informou explicitamente statuses
// mas, por algum motivo, não retornou event,
// garantimos coerência sem depender do histórico.

if (
  Object.prototype.hasOwnProperty.call(
    changes,
    'statuses'
  ) &&
  estado.statuses &&
  !Object.prototype.hasOwnProperty.call(
    changes,
    'event'
  )
) {
  estado.event = 'current_status';
}

// ==================================================
// VALIDAÇÃO FINAL DE STATUS
// ==================================================

estado.statuses =
  normalizarStatuses(estado.statuses);

// Se já temos a nova estrutura,
// nunca manter status legado simultaneamente.

if (estado.statuses) {
  estado.status = null;
}

// ==================================================
// COERÊNCIA FINAL DO QUERY SHAPE
// ==================================================

// O Query Builder determinístico trabalha com:
//
// count
// list
// group
// ranking
//
// Garantimos aqui que campos estruturais antigos
// não contaminem uma nova forma de consulta.

if (intent === 'analytical_query') {
  // COUNT:
  //
  // representa total simples, portanto não usa
  // agrupamento nem limite de ranking.

  if (queryShape === 'count') {
    estado.group_by = null;
    estado.limit = null;
  }

  // LIST:
  //
  // representa registros individuais.

  if (queryShape === 'list') {
    estado.group_by = null;
    estado.limit = null;
  }

  // GROUP:
  //
  // usa group_by, porém não deve herdar
  // limit de ranking anterior.

  if (queryShape === 'group') {
    estado.limit = null;
  }

  // RANKING:
  //
  // NÃO inventamos group_by ou limit.
  //
  // Esses valores devem vir do Interpretador
  // ou do estado anterior compatível.
  //
  // Caso estejam ausentes, o novo endpoint
  // /chatbot/structured-query fará a validação.
}


// ==================================================
// COERÊNCIA FINAL DA COMPARAÇÃO
// ==================================================

if (
  intent === 'analytical_query' &&
  queryShape === 'comparison'
) {
  // comparison sempre representa comparação de totais,
  // não agrupamento ou ranking.
  estado.group_by = null;
  estado.limit = null;

  if (comparison) {
    const dimension =
      comparison.dimension;

    // A dimensão comparada não deve permanecer como
    // filtro comum no estado, pois cada lado receberá
    // seu próprio valor no backend.
    if (dimension === 'period') {
      estado.year = null;
      estado.month = null;
      estado.start_date = null;
      estado.end_date = null;
    }

    if (
      dimension === 'praca' ||
      dimension === 'store_name' ||
      dimension === 'location_term'
    ) {
      estado.praca = null;
      estado.store_name = null;
      estado.location_term = null;
    }

    if (dimension === 'status') {
      estado.status = null;
      estado.statuses = null;
      estado.event = 'current_status';
    }

    // Um filtro de campo ausente na mesma dimensão
    // comparada seria contraditório com os valores
    // explícitos dos dois lados.
    if (estado.missing_field === dimension) {
      estado.missing_field = null;
    }

    // A dimensão comparada também não pode permanecer
    // simultaneamente dentro de multi_filters.
    if (
      estado.multi_filters &&
      Object.prototype.hasOwnProperty.call(
        estado.multi_filters,
        dimension
      )
    ) {
      delete estado.multi_filters[dimension];

      if (Object.keys(estado.multi_filters).length === 0) {
        estado.multi_filters = null;
      }
    }

    if (
      dimension !== 'period' &&
      dimension !== 'praca' &&
      dimension !== 'store_name' &&
      dimension !== 'location_term' &&
      dimension !== 'status' &&
      Object.prototype.hasOwnProperty.call(
        estado,
        dimension
      )
    ) {
      estado[dimension] = null;
    }
  }
}

// ==================================================
// COERÊNCIA FINAL DA SELEÇÃO CONTEXTUAL
// ==================================================

const selectionAnterior =
  normalizarSelectionPersistida(
    anterior.selection_context
  );

let selectionInstrucao =
  normalizarSelectionInstrucao(
    interpretacao.selection_context
  );

// ==================================================
// FALLBACK DETERMINÍSTICO PARA REFERÊNCIAS CONTEXTUAIS
// ==================================================
//
// O Interpretador normalmente devolve selection_context.
// Porém, expressões curtas como "dessas lojas" são simples
// o bastante para serem resolvidas de forma determinística.
//
// Isso evita que uma falha pontual do LLM faça a consulta
// perder o conjunto selecionado e retornar todos os registros.

function normalizarMensagemContextual(valor) {
  return String(valor ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLocaleLowerCase('pt-BR')
    .replace(/\s+/g, ' ')
    .trim();
}

function detectarDimensaoContextual(texto) {
  const regras = [
    {
      dimension: 'store_name',
      regex: /\b(?:dessas|dessas mesmas|essas|estas|destas) lojas\b/,
    },
    {
      dimension: 'category',
      regex: /\b(?:dessas|essas|estas|destas) categorias\b/,
    },
    {
      dimension: 'subcategory',
      regex: /\b(?:dessas|essas|estas|destas) subcategorias\b/,
    },
    {
      dimension: 'supplier',
      regex: /\b(?:desses|esses|destes) (?:fornecedores|prestadores)\b/,
    },
    {
      dimension: 'analyst_responsible',
      regex: /\b(?:desses|esses|destes) analistas\b/,
    },
    {
      dimension: 'requester',
      regex: /\b(?:desses|esses|destes) (?:requisitantes|solicitantes)\b/,
    },
    {
      dimension: 'praca',
      regex: /\b(?:dessas|essas|estas|destas) pracas\b/,
    },
    {
      dimension: 'location_term',
      regex: /\b(?:desses|esses|destes) locais\b/,
    },
  ];

  for (const regra of regras) {
    if (regra.regex.test(texto)) {
      return regra.dimension;
    }
  }

  return null;
}

function construirInstrucaoContextualFallback(
  mensagem,
  comparisonFonte
) {
  if (!comparisonFonte) {
    return null;
  }

  const texto =
    normalizarMensagemContextual(mensagem);

  const dimension =
    detectarDimensaoContextual(texto);

  if (!dimension) {
    return null;
  }

  const mencionaCompensacao =
    /\bcompens|sentido contrario|movimento contrario|aumentaram enquanto|cresceram enquanto/.test(texto);

  if (
    comparisonFonte.analysis_mode === 'drivers' &&
    Array.isArray(comparisonFonte.driver_dimensions) &&
    comparisonFonte.driver_dimensions.includes(dimension)
  ) {
    return {
      source: 'previous_comparison',
      mode: mencionaCompensacao
        ? 'offsets'
        : 'top_drivers',
      dimension,
      limit: comparisonFonte.driver_limit ?? null,
    };
  }

  if (comparisonFonte.breakdown_by === dimension) {
    return {
      source: 'previous_comparison',
      mode: 'breakdown',
      dimension,
      limit: comparisonFonte.breakdown_limit ?? null,
    };
  }

  if (comparisonFonte.dimension === dimension) {
    return {
      source: 'previous_comparison',
      mode: 'comparison_items',
      dimension,
      limit: null,
    };
  }

  return null;
}

if (!selectionInstrucao) {
  const comparisonFonteFallback =
    comparisonAnterior ??
    selectionAnterior?.source_comparison ??
    null;

  selectionInstrucao =
    construirInstrucaoContextualFallback(
      $('When chat message received')
        .first()
        .json
        .chatInput,
      comparisonFonteFallback
    );
}

let selectionContext =
  selectionAnterior;

// Remoção explícita sempre prevalece.
if (clearFields.includes('selection_context')) {
  selectionContext = null;
}

// Uma nova referência contextual é enriquecida com
// o estado e a comparação ANTERIORES. O LLM nunca
// precisa copiar os nomes reais dos grupos.
if (selectionInstrucao) {
  const sourceComparison =
    comparisonAnterior ??
    selectionAnterior?.source_comparison ??
    null;

  const sourceState =
    comparisonAnterior
      ? estadoAnteriorParaSelecao
      : selectionAnterior?.source_state ?? null;

  if (sourceComparison && sourceState) {
    selectionContext = {
      ...selectionInstrucao,
      source_state:
        JSON.parse(JSON.stringify(sourceState)),
      source_comparison:
        JSON.parse(JSON.stringify(sourceComparison)),
    };
  } else {
    selectionContext = null;
  }
}

// Uma comparação nova não deve herdar seleção antiga
// por acidente. Se a própria mensagem referenciou o
// conjunto anterior, selectionInstrucao estará presente.
if (
  queryShape === 'comparison' &&
  !selectionInstrucao
) {
  selectionContext = null;
}

// Filtro explícito na MESMA dimensão substitui a
// seleção contextual anterior.
if (selectionContext) {
  const dimension =
    selectionContext.dimension;

  const alterouSingular =
    Object.prototype.hasOwnProperty.call(
      changes,
      dimension
    ) &&
    changes[dimension] !== null &&
    changes[dimension] !== undefined;

  const alterouMultiplo =
    multiFiltersChanges &&
    Object.prototype.hasOwnProperty.call(
      multiFiltersChanges,
      dimension
    );

  const alterouStatus =
    dimension === 'status' &&
    (
      Object.prototype.hasOwnProperty.call(
        changes,
        'statuses'
      ) ||
      Object.prototype.hasOwnProperty.call(
        changes,
        'status'
      )
    );

  if (
    alterouSingular ||
    alterouMultiplo ||
    alterouStatus
  ) {
    selectionContext = null;
  }
}

// Se o usuário redefine explicitamente a própria
// dimensão que originou o escopo da comparação, a
// seleção contextual antiga deixa de ser compatível.
if (selectionContext) {
  const sourceDimension =
    selectionContext.source_comparison?.dimension;

  let redefiniuEscopo = false;

  if (sourceDimension === 'period') {
    redefiniuEscopo = [
      'date_field',
      'year',
      'month',
      'start_date',
      'end_date',
    ].some(campo =>
      Object.prototype.hasOwnProperty.call(
        changes,
        campo
      )
    );
  } else if (sourceDimension === 'status') {
    redefiniuEscopo =
      Object.prototype.hasOwnProperty.call(
        changes,
        'statuses'
      ) ||
      Object.prototype.hasOwnProperty.call(
        changes,
        'status'
      );
  } else if (sourceDimension) {
    redefiniuEscopo =
      Object.prototype.hasOwnProperty.call(
        changes,
        sourceDimension
      ) ||
      (
        multiFiltersChanges &&
        Object.prototype.hasOwnProperty.call(
          multiFiltersChanges,
          sourceDimension
        )
      );
  }

  if (redefiniuEscopo) {
    selectionContext = null;
  }
}

if (intent !== 'analytical_query') {
  selectionContext = null;
}

// Ao sair de comparison, o objeto de comparação não
// participa mais da consulta atual. O snapshot usado
// pela seleção contextual permanece separado.
if (queryShape !== 'comparison') {
  comparison = null;
}

// ==================================================
// COERÊNCIA FINAL DO RESPONSE FORMAT
// ==================================================

// Somente LIST utiliza response_format.
//
// Para count, group, ranking, comparison, explain_source
// e clarification, o valor deve ser null.

if (
  intent !== 'analytical_query' ||
  queryShape !== 'list'
) {
  responseFormat = null;
}

// Proteção final para listagens.
// Toda listagem precisa possuir um formato válido.

if (
  intent === 'analytical_query' &&
  queryShape === 'list' &&
  !responseFormat
) {
  responseFormat = 'detailed_list';
}

// ==================================================
// RETORNO
// ==================================================

return [
  {
    json: {
      session_id:
        $('When chat message received')
          .first()
          .json
          .sessionId,

      intent,

      query_shape:
        queryShape,

      response_format:
        responseFormat,

      comparison:
        comparison,

      selection_context:
        selectionContext,

      display_fields:
        displayFields,

      ...estado,
    },
  },
];

const resultado = $input.first().json;
const trigger = $('When chat message received').first().json;

const finalState =
  $('Mesclar Estado da Consulta').first().json ?? {};

const isQa =
  trigger.qaMode === true ||
  String(trigger.qaMode).toLowerCase() === 'true';

// ==================================================
// HELPERS
// ==================================================

function textoLimpo(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return '';
  }

  return String(valor)
    .replace(/\n/g, ' ')
    .replace(/\r/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function valorTexto(valor) {
  const texto = textoLimpo(valor);

  return texto || '—';
}

function valorDetalhado(campo, valor) {
  const texto = textoLimpo(valor);

  if (texto) {
    return texto;
  }

  if (
    campo === 'supplier' ||
    campo === 'analyst_responsible'
  ) {
    return 'Não atribuído';
  }

  if (campo === 'service_description') {
    return 'Não informada';
  }

  if (
    campo === 'created_on' ||
    campo === 'completion_date' ||
    campo === 'visit_date'
  ) {
    return 'Não informada';
  }

  return 'Não informado';
}

function formatarData(valor) {
  if (!valor) {
    return 'Não informada';
  }

  const texto = String(valor);

  // Aceita:
  //
  // 2026-09-23
  // 2026-09-23T10:30:00
  // 2026-09-23 10:30:00
  // 2026-09-23T10:30:00.000Z

  const match = texto.match(
    /^(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{2}):(\d{2}))?/
  );

  if (!match) {
    return texto;
  }

  const data =
    `${match[3]}/${match[2]}/${match[1]}`;

  if (match[4] && match[5]) {
    return `${data} ${match[4]}:${match[5]}`;
  }

  return data;
}

function escaparMarkdown(valor) {
  return valorTexto(valor)
    .replace(/\|/g, '\\|')
    .replace(/\n/g, ' ')
    .replace(/\r/g, ' ');
}

function juntarNatural(lista) {
  const valores =
    lista.filter(Boolean);

  if (valores.length === 0) {
    return '';
  }

  if (valores.length === 1) {
    return valores[0];
  }

  if (valores.length === 2) {
    return `${valores[0]} e ${valores[1]}`;
  }

  return `${valores
    .slice(0, -1)
    .join(', ')} e ${valores[valores.length - 1]}`;
}

function capitalizarPrimeira(texto) {
  if (!texto) {
    return '';
  }

  return (
    texto.charAt(0).toUpperCase() +
    texto.slice(1)
  );
}

// ==================================================
// LABELS
// ==================================================

const LABELS = {
  ticket: 'Ticket',
  status: 'Status',

  created_on: 'Data de Abertura',

  store_name: 'Loja',
  praca: 'Praça',

  category: 'Categoria',
  subcategory: 'Subcategoria',

  service_description: 'Descrição',

  analyst_responsible:
    'Analista Responsável',

  supplier: 'Fornecedor',

  requester: 'Requisitante',

  completion_date:
    'Data de Conclusão',

  visit_date:
    'Data da Visita',

  total: 'Total',
};

function labelCampo(campo) {
  return LABELS[campo] ?? campo;
}

// ==================================================
// PERÍODO EM LINGUAGEM NATURAL
// ==================================================

const MESES = {
  1: 'janeiro',
  2: 'fevereiro',
  3: 'março',
  4: 'abril',
  5: 'maio',
  6: 'junho',
  7: 'julho',
  8: 'agosto',
  9: 'setembro',
  10: 'outubro',
  11: 'novembro',
  12: 'dezembro',
};

function montarPeriodoNatural(state) {
  if (
    state.start_date ||
    state.end_date
  ) {
    if (
      state.start_date &&
      state.end_date
    ) {
      return (
        `entre **${formatarData(
          state.start_date
        )}** e **${formatarData(
          state.end_date
        )}**`
      );
    }

    if (state.start_date) {
      return (
        `a partir de **${formatarData(
          state.start_date
        )}**`
      );
    }

    return (
      `até **${formatarData(
        state.end_date
      )}**`
    );
  }

  if (
    state.year &&
    state.month
  ) {
    const mes =
      MESES[Number(state.month)] ??
      String(state.month);

    return (
      `em **${mes} de ${state.year}**`
    );
  }

  if (state.year) {
    return `em **${state.year}**`;
  }

  return '';
}

// ==================================================
// LOCAL EM LINGUAGEM NATURAL
// ==================================================

function montarLocalNatural(state) {
  if (state.praca) {
    return (
      ` na praça **${textoLimpo(
        state.praca
      )}**`
    );
  }

  if (state.store_name) {
    return (
      ` na loja **${textoLimpo(
        state.store_name
      )}**`
    );
  }

  if (state.location_term) {
    return (
      ` em **${textoLimpo(
        state.location_term
      )}**`
    );
  }

  return '';
}

// ==================================================
// STATUS EM LINGUAGEM NATURAL
// ==================================================

function statusUnicoNatural(
  status,
  total
) {
  const plural =
    total !== 1;

  switch (status) {
    case 'Em Aberto':
      return 'em aberto';

    case 'Em atendimento':
      return 'em atendimento';

    case 'Pendente de aprovação':
      return plural
        ? 'pendentes de aprovação'
        : 'pendente de aprovação';

    case 'Não Aprovado':
      return plural
        ? 'não aprovados'
        : 'não aprovado';

    case 'Concluído':
      return plural
        ? 'concluídos'
        : 'concluído';

    default:
      return '';
  }
}

function montarStatusNatural(
  state,
  total
) {
  if (
    !Array.isArray(state.statuses) ||
    state.statuses.length === 0
  ) {
    return '';
  }

  if (state.statuses.length === 1) {
    const status =
      statusUnicoNatural(
        state.statuses[0],
        total
      );

    return status
      ? ` ${status}`
      : '';
  }

  const statuses =
    state.statuses.map(
      status => `**${status}**`
    );

  return (
    ` com status ${juntarNatural(
      statuses
    )}`
  );
}

// ==================================================
// FILTROS SECUNDÁRIOS EM LINGUAGEM NATURAL
// ==================================================

function montarAusenciaNatural(
  campo
) {
  switch (campo) {
    case 'supplier':
      return ' sem fornecedor atribuído';

    case 'analyst_responsible':
      return ' sem analista responsável atribuído';

    case 'requester':
      return ' sem requisitante informado';

    case 'category':
      return ' sem categoria informada';

    case 'subcategory':
      return ' sem subcategoria informada';

    case 'store_name':
      return ' sem loja informada';

    case 'praca':
      return ' sem praça informada';

    default:
      return campo
        ? ` sem ${labelCampo(campo).toLowerCase()} informado`
        : '';
  }
}

function montarFiltrosSecundarios(
  state
) {
  let texto = '';

  if (state.category) {
    texto += (
      ` na categoria **${textoLimpo(
        state.category
      )}**`
    );

    if (state.subcategory) {
      texto += (
        ` > **${textoLimpo(
          state.subcategory
        )}**`
      );
    }
  } else if (state.subcategory) {
    texto += (
      ` na subcategoria **${textoLimpo(
        state.subcategory
      )}**`
    );
  }

  if (state.analyst_responsible) {
    texto += (
      ` sob responsabilidade de **${textoLimpo(
        state.analyst_responsible
      )}**`
    );
  }

  if (state.supplier) {
    texto += (
      ` com o fornecedor **${textoLimpo(
        state.supplier
      )}**`
    );
  }

  if (state.requester) {
    texto += (
      ` solicitados por **${textoLimpo(
        state.requester
      )}**`
    );
  }

  if (state.missing_field) {
    texto +=
      montarAusenciaNatural(
        state.missing_field
      );
  }

  return texto;
}

// ==================================================
// FRASE HUMANA DE RESUMO
// ==================================================

function montarFraseResumo(
  total,
  state
) {
  const nome =
    total === 1
      ? 'chamado'
      : 'chamados';

  const local =
    montarLocalNatural(state);

  const extras =
    montarFiltrosSecundarios(state);

  const periodo =
    montarPeriodoNatural(state);

  // -----------------------------------------------
  // SITUAÇÃO ATUAL
  // -----------------------------------------------

  if (
    state.event === 'current_status'
  ) {
    const status =
      montarStatusNatural(
        state,
        total
      );

    // Coorte histórica + status atual
    //
    // Exemplo:
    // "Dos chamados criados em agosto,
    // 42 ainda estão em atendimento."

    if (
      state.date_field &&
      periodo
    ) {
      let tipoCoorte =
        'considerados';

      if (
        state.date_field ===
        'created_on'
      ) {
        tipoCoorte = 'criados';
      }

      if (
        state.date_field ===
        'completion_date'
      ) {
        tipoCoorte = 'concluídos';
      }

      if (
        state.date_field ===
        'visit_date'
      ) {
        tipoCoorte =
          'que tiveram visita';
      }

      if (
        Array.isArray(
          state.statuses
        ) &&
        state.statuses.length === 1
      ) {
        return (
          `Dos chamados ${tipoCoorte} ${periodo}, ` +
          `**${total}** ${
            total === 1
              ? 'está'
              : 'estão'
          }${status}${local}${extras}.`
        );
      }

      return (
        `Dos chamados ${tipoCoorte} ${periodo}, ` +
        `**${total}** ${nome} atendem aos filtros atuais` +
        `${local}${extras}.`
      );
    }

    return (
      `Atualmente, há **${total}** ` +
      `${nome}${status}${local}${extras}.`
    );
  }

  // -----------------------------------------------
  // ABERTOS / CRIADOS
  // -----------------------------------------------

  if (state.event === 'opened') {
    const frasePeriodo =
      periodo
        ? `${capitalizarPrimeira(
            periodo
          )}, `
        : '';

    if (total === 1) {
      return (
        `${frasePeriodo}${frasePeriodo ? 'foi' : 'Foi'} aberto ` +
        `**1 chamado**${local}${extras}.`
      );
    }

    return (
      `${frasePeriodo}${frasePeriodo ? 'foram' : 'Foram'} abertos ` +
      `**${total} chamados**${local}${extras}.`
    );
  }

  // -----------------------------------------------
  // CONCLUÍDOS
  // -----------------------------------------------

  if (state.event === 'completed') {
    const frasePeriodo =
      periodo
        ? `${capitalizarPrimeira(
            periodo
          )}, `
        : '';

    if (total === 1) {
      return (
        `${frasePeriodo}${frasePeriodo ? 'foi' : 'Foi'} concluído ` +
        `**1 chamado**${local}${extras}.`
      );
    }

    return (
      `${frasePeriodo}${frasePeriodo ? 'foram' : 'Foram'} concluídos ` +
      `**${total} chamados**${local}${extras}.`
    );
  }

  // -----------------------------------------------
  // VISITAS
  // -----------------------------------------------

  if (state.event === 'visited') {
    const frasePeriodo =
      periodo
        ? `${capitalizarPrimeira(
            periodo
          )}, `
        : '';

    if (total === 1) {
      return (
        `${frasePeriodo}${frasePeriodo ? 'foi' : 'Foi'} registrado ` +
        `**1 chamado com visita**${local}${extras}.`
      );
    }

    return (
      `${frasePeriodo}${frasePeriodo ? 'foram' : 'Foram'} registrados ` +
      `**${total} chamados com visita**${local}${extras}.`
    );
  }

  // -----------------------------------------------
  // FALLBACK
  // -----------------------------------------------

  return (
    `Há **${total}** ${nome}` +
    `${local}${extras}.`
  );
}

// ==================================================
// FILTROS UTILIZADOS
// ==================================================

function montarResumoFiltros(state) {
  const filtros = [];

  if (state.praca) {
    filtros.push(
      `Praça: **${state.praca}**`
    );
  }

  if (state.store_name) {
    filtros.push(
      `Loja: **${state.store_name}**`
    );
  }

  if (state.location_term) {
    filtros.push(
      `Local: **${state.location_term}**`
    );
  }

  if (
    Array.isArray(state.statuses) &&
    state.statuses.length > 0
  ) {
    filtros.push(
      `Status: **${state.statuses.join(
        ', '
      )}**`
    );
  }

  if (state.analyst_responsible) {
    filtros.push(
      `Analista: **${state.analyst_responsible}**`
    );
  }

  if (state.supplier) {
    filtros.push(
      `Fornecedor: **${state.supplier}**`
    );
  }

  if (state.requester) {
    filtros.push(
      `Requisitante: **${state.requester}**`
    );
  }

  if (state.category) {
    filtros.push(
      `Categoria: **${state.category}**`
    );
  }

  if (state.subcategory) {
    filtros.push(
      `Subcategoria: **${state.subcategory}**`
    );
  }

  if (
    state.multi_filters &&
    typeof state.multi_filters === 'object' &&
    !Array.isArray(state.multi_filters)
  ) {
    const labelsMultiplos = {
      praca: 'Praças',
      store_name: 'Lojas',
      location_term: 'Locais',
      analyst_responsible: 'Analistas',
      supplier: 'Fornecedores',
      requester: 'Requisitantes',
      category: 'Categorias',
      subcategory: 'Subcategorias',
    };

    for (const [dimension, valores] of Object.entries(state.multi_filters)) {
      if (
        !Array.isArray(valores) ||
        valores.length === 0
      ) {
        continue;
      }

      const label =
        labelsMultiplos[dimension] ??
        labelCampo(dimension);

      filtros.push(
        `${label}: **${valores.join(', ')}**`
      );
    }
  }

  if (state.missing_field) {
    filtros.push(
      `Sem preenchimento em: **${labelCampo(
        state.missing_field
      )}**`
    );
  }

  if (
    state.year &&
    state.month
  ) {
    filtros.push(
      `Período: **${String(
        state.month
      ).padStart(
        2,
        '0'
      )}/${state.year}**`
    );
  } else if (state.year) {
    filtros.push(
      `Ano: **${state.year}**`
    );
  }

  if (
    state.start_date ||
    state.end_date
  ) {
    const inicio =
      state.start_date
        ? formatarData(
            state.start_date
          )
        : 'início';

    const fim =
      state.end_date
        ? formatarData(
            state.end_date
          )
        : 'hoje';

    filtros.push(
      `Período: **${inicio} a ${fim}**`
    );
  }

  return filtros.length > 0
    ? filtros.join(' · ')
    : null;
}

// ==================================================
// SELEÇÃO CONTEXTUAL RESOLVIDA
// ==================================================

function montarResumoSelecaoResolvida(selection) {
  if (
    !selection ||
    !Array.isArray(selection.values)
  ) {
    return '';
  }

  const dimension =
    selection.dimension;

  const valores =
    selection.values
      .map(textoLimpo)
      .filter(Boolean);

  if (valores.length === 0) {
    return 'A seleção contextual da análise anterior não retornou grupos para aplicar nesta consulta.';
  }

  const frases = {
    praca: 'Considerei as praças selecionadas na análise anterior',
    store_name: 'Considerei as lojas selecionadas na análise anterior',
    location_term: 'Considerei os locais selecionados na análise anterior',
    analyst_responsible: 'Considerei os analistas selecionados na análise anterior',
    supplier: 'Considerei os fornecedores selecionados na análise anterior',
    requester: 'Considerei os requisitantes selecionados na análise anterior',
    category: 'Considerei as categorias selecionadas na análise anterior',
    subcategory: 'Considerei as subcategorias selecionadas na análise anterior',
    status: 'Considerei os status selecionados na análise anterior',
  };

  const prefixo =
    frases[dimension] ??
    `Considerei a seleção anterior por ${labelCampo(dimension)}`;

  const valoresTexto =
    valores
      .map(valor => `**${valor}**`)
      .join(', ');

  let texto =
    `${prefixo}: ${valoresTexto}.`;

  if (selection.inherited_comparison_scope === true) {
    texto +=
      ' Mantive também o escopo dos dois cenários da comparação anterior.';
  }

  return texto;
}

// ==================================================
// MARKDOWN TABLE
// ==================================================

function montarTabela(
  rows,
  campos
) {
  if (
    !Array.isArray(rows) ||
    rows.length === 0 ||
    !Array.isArray(campos) ||
    campos.length === 0
  ) {
    return '';
  }

  const cabecalho =
    `| ${campos
      .map(
        campo =>
          labelCampo(campo)
      )
      .join(' | ')} |`;

  const separador =
    `| ${campos
      .map(() => '---')
      .join(' | ')} |`;

  const linhas =
    rows.map(row => {
      const valores =
        campos.map(campo => {
          let valor =
            row[campo];

          if (
            campo === 'created_on' ||
            campo === 'completion_date' ||
            campo === 'visit_date'
          ) {
            valor =
              formatarData(valor);
          }

          return escaparMarkdown(
            valor
          );
        });

      return (
        `| ${valores.join(
          ' | '
        )} |`
      );
    });

  return [
    cabecalho,
    separador,
    ...linhas,
  ].join('\n');
}

// ==================================================
// LISTA DETALHADA
// ==================================================

function montarCategoriaSubcategoria(
  row
) {
  const categoria =
    textoLimpo(row.category);

  const subcategoria =
    textoLimpo(row.subcategory);

  if (
    categoria &&
    subcategoria
  ) {
    return (
      `${categoria} > ${subcategoria}`
    );
  }

  if (categoria) {
    return categoria;
  }

  if (subcategoria) {
    return subcategoria;
  }

  return 'Não informado';
}

function montarListaDetalhada(
  rows,
  displayFields
) {
  const extrasOrdenados = [
    'praca',
    'analyst_responsible',
    'supplier',
    'requester',
    'completion_date',
    'visit_date',
  ].filter(
    campo =>
      displayFields.includes(campo)
  );

  return rows
    .map(
      (row, index) => {
        const linhas = [];

        const ticket =
          valorDetalhado(
            'ticket',
            row.ticket
          );

        linhas.push(
          `${index + 1}. **Chamado ${ticket}**`
        );

        linhas.push(
          `   - **Status:** ${valorDetalhado(
            'status',
            row.status
          )}`
        );

        linhas.push(
          `   - **Data de Abertura:** ${formatarData(
            row.created_on
          )}`
        );

        linhas.push(
          `   - **Loja:** ${valorDetalhado(
            'store_name',
            row.store_name
          )}`
        );

        linhas.push(
          `   - **Categoria / Subcategoria:** ${montarCategoriaSubcategoria(
            row
          )}`
        );

        for (
          const campo of extrasOrdenados
        ) {
          let valor =
            row[campo];

          if (
            campo ===
              'completion_date' ||
            campo === 'visit_date'
          ) {
            valor =
              formatarData(valor);
          } else {
            valor =
              valorDetalhado(
                campo,
                valor
              );
          }

          linhas.push(
            `   - **${labelCampo(
              campo
            )}:** ${valor}`
          );
        }

        linhas.push(
          `   - **Descrição:** ${valorDetalhado(
            'service_description',
            row.service_description
          )}`
        );

        return linhas.join('\n');
      }
    )
    .join('\n\n');
}


// ==================================================
// COMPARAÇÃO — LINGUAGEM NATURAL
// ==================================================

function formatarNumeroPtBr(
  valor,
  casas = 0
) {
  const numero = Number(valor);

  if (!Number.isFinite(numero)) {
    return '0';
  }

  return numero.toLocaleString(
    'pt-BR',
    {
      minimumFractionDigits: casas,
      maximumFractionDigits: casas,
    }
  );
}

function nomeChamados(total) {
  return Number(total) === 1
    ? 'chamado'
    : 'chamados';
}

function contextoComparacao(state) {
  if (state.event === 'opened') {
    return 'chamados abertos';
  }

  if (state.event === 'completed') {
    return 'chamados concluídos';
  }

  if (state.event === 'visited') {
    return 'chamados com visita';
  }

  if (
    state.event === 'current_status' &&
    Array.isArray(state.statuses) &&
    state.statuses.length === 1
  ) {
    const status =
      statusUnicoNatural(
        state.statuses[0],
        2
      );

    return status
      ? `chamados ${status}`
      : 'chamados';
  }

  return 'chamados';
}

function montarRespostaComparacao(
  resultadoComparacao,
  rowsComparacao,
  state
) {
  if (
    !resultadoComparacao ||
    !Array.isArray(rowsComparacao) ||
    rowsComparacao.length < 2
  ) {
    return 'A comparação foi executada, mas os dados retornados estão incompletos.';
  }

  const primeiro = rowsComparacao[0];
  const segundo = rowsComparacao[1];

  const labelBase =
    textoLimpo(
      resultadoComparacao.base_label ??
      primeiro.label
    ) || 'Primeiro item';

  const labelAlvo =
    textoLimpo(
      resultadoComparacao.target_label ??
      segundo.label
    ) || 'Segundo item';

  const totalBase =
    Number(primeiro.total ?? 0);

  const totalAlvo =
    Number(segundo.total ?? 0);

  const diferenca =
    Number(
      resultadoComparacao.difference ??
      (totalAlvo - totalBase)
    );

  const percentual =
    resultadoComparacao.percentage_change;

  const direcao =
    resultadoComparacao.direction ??
    (
      diferenca > 0
        ? 'increase'
        : diferenca < 0
          ? 'decrease'
          : 'stable'
    );

  let outputComparacao = '';

  const dimension =
    resultadoComparacao.dimension;

  // Para comparação histórica por período, usamos
  // frases mais naturais em vez de uma tabela/lista.
  if (
    dimension === 'period' &&
    state.event === 'opened'
  ) {
    outputComparacao =
      `Em **${labelBase}**, foram abertos **${formatarNumeroPtBr(
        totalBase
      )} ${nomeChamados(totalBase)}**. ` +
      `Em **${labelAlvo}**, foram abertos **${formatarNumeroPtBr(
        totalAlvo
      )} ${nomeChamados(totalAlvo)}**.`;
  } else if (
    dimension === 'period' &&
    state.event === 'completed'
  ) {
    outputComparacao =
      `Em **${labelBase}**, foram concluídos **${formatarNumeroPtBr(
        totalBase
      )} ${nomeChamados(totalBase)}**. ` +
      `Em **${labelAlvo}**, foram concluídos **${formatarNumeroPtBr(
        totalAlvo
      )} ${nomeChamados(totalAlvo)}**.`;
  } else if (
    dimension === 'period' &&
    state.event === 'visited'
  ) {
    outputComparacao =
      `Em **${labelBase}**, **${formatarNumeroPtBr(
        totalBase
      )} ${nomeChamados(totalBase)}** tiveram visita registrada. ` +
      `Em **${labelAlvo}**, foram **${formatarNumeroPtBr(
        totalAlvo
      )} ${nomeChamados(totalAlvo)}**.`;
  } else {
    outputComparacao =
      `Comparei a quantidade de **${contextoComparacao(
        state
      )}** entre os dois cenários:`;

    outputComparacao +=
      `\n\n- **${labelBase}:** **${formatarNumeroPtBr(
        totalBase
      )}** ${nomeChamados(totalBase)}`;

    outputComparacao +=
      `\n- **${labelAlvo}:** **${formatarNumeroPtBr(
        totalAlvo
      )}** ${nomeChamados(totalAlvo)}`;
  }

  if (direcao === 'stable') {
    outputComparacao +=
      `\n\nNão houve variação entre **${labelBase}** e **${labelAlvo}**.`;

    return outputComparacao;
  }

  const absoluto =
    Math.abs(diferenca);

  const movimento =
    direcao === 'increase'
      ? 'aumento'
      : 'redução';

  const artigo =
    direcao === 'increase'
      ? 'um'
      : 'uma';

  outputComparacao +=
    `\n\nDe **${labelBase}** para **${labelAlvo}**, houve ` +
    `${artigo} **${movimento} de ${formatarNumeroPtBr(
      absoluto
    )} ${nomeChamados(absoluto)}**`;

  if (
    percentual === null ||
    percentual === undefined ||
    !Number.isFinite(Number(percentual))
  ) {
    outputComparacao +=
      '. Como o primeiro valor é zero, a variação percentual não é aplicável.';
  } else {
    outputComparacao +=
      `, equivalente a **${formatarNumeroPtBr(
        Math.abs(Number(percentual)),
        2
      )}%**.`;
  }

  return outputComparacao;
}

// ==================================================
// DETALHAMENTO ANALÍTICO DA COMPARAÇÃO
// ==================================================

function rotuloBreakdown(campo) {
  const plural = {
    praca: 'praças',
    store_name: 'lojas',
    analyst_responsible: 'analistas',
    supplier: 'fornecedores',
    requester: 'requisitantes',
    category: 'categorias',
    subcategory: 'subcategorias',
    status: 'status',
  };

  return plural[campo] ?? 'grupos';
}

function montarDetalhamentoComparacao(
  resultadoComparacao,
  breakdown
) {
  const breakdownBy =
    resultadoComparacao?.breakdown_by ?? null;

  if (!breakdownBy) {
    return '';
  }

  const ordem =
    resultadoComparacao?.breakdown_order ??
    'absolute_change';

  const rotulo =
    rotuloBreakdown(breakdownBy);

  if (
    !Array.isArray(breakdown) ||
    breakdown.length === 0
  ) {
    if (ordem === 'decrease') {
      return `Não houve ${rotulo} com redução entre os dois cenários.`;
    }

    if (ordem === 'increase') {
      return `Não houve ${rotulo} com aumento entre os dois cenários.`;
    }

    return `Não houve variação por ${labelCampo(breakdownBy)} entre os dois cenários.`;
  }

  let titulo;

  if (ordem === 'decrease') {
    titulo = `As ${rotulo} com maior redução foram:`;
  } else if (ordem === 'increase') {
    titulo = `As ${rotulo} com maior aumento foram:`;
  } else {
    titulo = `As maiores variações por **${labelCampo(
      breakdownBy
    )}** foram:`;
  }

  const baseLabel =
    textoLimpo(
      resultadoComparacao?.base_label
    ) || 'Cenário inicial';

  const targetLabel =
    textoLimpo(
      resultadoComparacao?.target_label
    ) || 'Cenário final';

  const linhas = breakdown.map(
    (item, index) => {
      const label =
        textoLimpo(item.label) ||
        'Não informado';

      const baseTotal =
        Number(item.base_total ?? 0);

      const targetTotal =
        Number(item.target_total ?? 0);

      const diferenca =
        Number(
          item.difference ??
          (targetTotal - baseTotal)
        );

      const direcao =
        item.direction ??
        (
          diferenca > 0
            ? 'increase'
            : diferenca < 0
              ? 'decrease'
              : 'stable'
        );

      let movimento;

      if (direcao === 'increase') {
        movimento =
          `aumento de **${formatarNumeroPtBr(
            Math.abs(diferenca)
          )} ${nomeChamados(
            Math.abs(diferenca)
          )}**`;
      } else if (direcao === 'decrease') {
        movimento =
          `redução de **${formatarNumeroPtBr(
            Math.abs(diferenca)
          )} ${nomeChamados(
            Math.abs(diferenca)
          )}**`;
      } else {
        movimento = 'sem variação';
      }

      const percentual =
        item.percentage_change;

      let percentualTexto = '';

      if (
        direcao !== 'stable' &&
        percentual !== null &&
        percentual !== undefined &&
        Number.isFinite(Number(percentual))
      ) {
        percentualTexto =
          `, equivalente a **${formatarNumeroPtBr(
            Math.abs(Number(percentual)),
            2
          )}%**`;
      } else if (
        direcao !== 'stable' &&
        baseTotal === 0
      ) {
        percentualTexto =
          ', com percentual não aplicável porque o valor inicial era zero';
      }

      return (
        `${index + 1}. **${label}** — ` +
        `**${baseLabel}: ${formatarNumeroPtBr(
          baseTotal
        )}** | ` +
        `**${targetLabel}: ${formatarNumeroPtBr(
          targetTotal
        )}** — ` +
        `${movimento}${percentualTexto}.`
      );
    }
  );

  return `${titulo}\n\n${linhas.join('\n')}`;
}

// ==================================================
// DRIVERS DA VARIAÇÃO — DECOMPOSIÇÃO DETERMINÍSTICA
// ==================================================

function montarLinhaDriver(
  item,
  baseLabel,
  targetLabel,
  mostrarContribuicao = true
) {
  const label =
    textoLimpo(item?.label) ||
    'Não informado';

  const baseTotal =
    Number(item?.base_total ?? 0);

  const targetTotal =
    Number(item?.target_total ?? 0);

  const diferenca =
    Number(
      item?.difference ??
      (targetTotal - baseTotal)
    );

  const direcao =
    item?.direction ??
    (
      diferenca > 0
        ? 'increase'
        : diferenca < 0
          ? 'decrease'
          : 'stable'
    );

  const movimento =
    direcao === 'increase'
      ? `aumento de **${formatarNumeroPtBr(
          Math.abs(diferenca)
        )} ${nomeChamados(
          Math.abs(diferenca)
        )}**`
      : direcao === 'decrease'
        ? `redução de **${formatarNumeroPtBr(
            Math.abs(diferenca)
          )} ${nomeChamados(
            Math.abs(diferenca)
          )}**`
        : 'sem variação';

  let contribuicaoTexto = '';

  const contribuicao =
    item?.contribution_pct;

  if (
    mostrarContribuicao &&
    contribuicao !== null &&
    contribuicao !== undefined &&
    Number.isFinite(Number(contribuicao))
  ) {
    if (Number(contribuicao) >= 0) {
      contribuicaoTexto =
        `; contribuição para a variação líquida: **${formatarNumeroPtBr(
          Number(contribuicao),
          2
        )}%**`;
    } else {
      contribuicaoTexto =
        `; movimento em sentido contrário equivalente a **${formatarNumeroPtBr(
          Math.abs(Number(contribuicao)),
          2
        )}%** da variação líquida`;
    }
  }

  return (
    `**${label}** — ` +
    `**${baseLabel}: ${formatarNumeroPtBr(
      baseTotal
    )}** | ` +
    `**${targetLabel}: ${formatarNumeroPtBr(
      targetTotal
    )}** — ` +
    `${movimento}${contribuicaoTexto}.`
  );
}

function montarAnaliseDrivers(
  resultadoComparacao,
  driverAnalysis
) {
  if (
    !driverAnalysis ||
    driverAnalysis.mode !== 'drivers' ||
    !Array.isArray(driverAnalysis.dimensions) ||
    driverAnalysis.dimensions.length === 0
  ) {
    return '';
  }

  const netDifference =
    Number(
      driverAnalysis.net_difference ??
      resultadoComparacao?.difference ??
      0
    );

  const direction =
    driverAnalysis.direction ??
    resultadoComparacao?.direction ??
    (
      netDifference > 0
        ? 'increase'
        : netDifference < 0
          ? 'decrease'
          : 'stable'
    );

  const baseLabel =
    textoLimpo(
      resultadoComparacao?.base_label
    ) || 'Cenário inicial';

  const targetLabel =
    textoLimpo(
      resultadoComparacao?.target_label
    ) || 'Cenário final';

  const netAbs =
    Math.abs(netDifference);

  let introducao = '';

  if (direction === 'decrease') {
    introducao =
      `A redução líquida de **${formatarNumeroPtBr(
        netAbs
      )} ${nomeChamados(netAbs)}** está concentrada nos grupos abaixo.`;
  } else if (direction === 'increase') {
    introducao =
      `O aumento líquido de **${formatarNumeroPtBr(
        netAbs
      )} ${nomeChamados(netAbs)}** está concentrado nos grupos abaixo.`;
  } else {
    introducao =
      'O total ficou estável, mas houve movimentos internos entre os grupos que se compensaram.';
  }

  introducao +=
    ' Esta análise mostra **onde a variação ocorreu nos dados**; ela não atribui, por si só, uma causa operacional.';

  if (driverAnalysis.dimensions.length > 1) {
    introducao +=
      ' As dimensões abaixo são **leituras alternativas da mesma variação** e não devem ser somadas entre si.';
  }

  const blocos =
    driverAnalysis.dimensions.map(
      dimensao => {
        const campo =
          dimensao?.dimension;

        const titulo =
          `**Por ${labelCampo(campo)}**`;

        const drivers =
          Array.isArray(
            dimensao?.top_drivers
          )
            ? dimensao.top_drivers
            : [];

        const offsets =
          Array.isArray(
            dimensao?.offsets
          )
            ? dimensao.offsets
            : [];

        const grossDriver =
          Number(
            dimensao?.gross_driver_change ??
            0
          );

        const grossOffset =
          Number(
            dimensao?.gross_offset_change ??
            0
          );

        const partes = [titulo];

        if (drivers.length === 0) {
          partes.push(
            'Não houve grupos com variação relevante nesta dimensão.'
          );
        } else {
          if (direction === 'stable') {
            partes.push(
              'Maiores movimentos internos:'
            );
          } else if (direction === 'decrease') {
            partes.push(
              'Principais grupos que puxaram a redução:'
            );
          } else {
            partes.push(
              'Principais grupos que puxaram o aumento:'
            );
          }

          const linhas =
            drivers.map(
              (item, index) =>
                `${index + 1}. ${montarLinhaDriver(
                  item,
                  baseLabel,
                  targetLabel,
                  direction !== 'stable'
                )}`
            );

          partes.push(linhas.join('\n'));
        }

        if (
          direction !== 'stable' &&
          grossDriver > 0
        ) {
          const verboDriver =
            direction === 'decrease'
              ? 'As reduções'
              : 'Os aumentos';

          let resumo =
            `${verboDriver} nesta dimensão somaram **${formatarNumeroPtBr(
              grossDriver
            )} ${nomeChamados(grossDriver)}**`;

          if (grossOffset > 0) {
            resumo +=
              `, enquanto movimentos no sentido contrário compensaram **${formatarNumeroPtBr(
                grossOffset
              )} ${nomeChamados(grossOffset)}**`;
          }

          resumo +=
            `, resultando no saldo líquido de **${formatarNumeroPtBr(
              netAbs
            )} ${nomeChamados(netAbs)}**.`;

          partes.push(resumo);
        } else if (
          direction === 'stable' &&
          (grossDriver > 0 || grossOffset > 0)
        ) {
          partes.push(
            `Nesta dimensão, aumentos de **${formatarNumeroPtBr(
              grossDriver
            )} ${nomeChamados(grossDriver)}** e reduções de **${formatarNumeroPtBr(
              grossOffset
            )} ${nomeChamados(grossOffset)}** se compensaram.`
          );
        }

        if (
          direction !== 'stable' &&
          offsets.length > 0
        ) {
          partes.push(
            direction === 'decrease'
              ? 'Movimentos que compensaram parte da redução:'
              : 'Movimentos que compensaram parte do aumento:'
          );

          const linhasOffset =
            offsets.map(
              item =>
                `- ${montarLinhaDriver(
                  item,
                  baseLabel,
                  targetLabel,
                  true
                )}`
            );

          partes.push(
            linhasOffset.join('\n')
          );
        }

        return partes.join('\n\n');
      }
    );

  return (
    `${introducao}\n\n${blocos.join('\n\n')}`
  );
}

// ==================================================
// DADOS DA CONSULTA
// ==================================================

const queryShape =
  resultado.query_shape ??
  finalState.query_shape ??
  null;

const responseFormat =
  queryShape === 'list'
    ? (
        finalState.response_format ===
        'table'
          ? 'table'
          : 'detailed_list'
      )
    : null;

const rows =
  Array.isArray(
    resultado.rows
  )
    ? resultado.rows
    : [];

const rowCount =
  Number.isInteger(
    resultado.row_count
  )
    ? resultado.row_count
    : rows.length;

const truncated =
  resultado.truncated === true;

const resumoFiltros =
  montarResumoFiltros(
    finalState
  );

const resumoSelecaoContextual =
  montarResumoSelecaoResolvida(
    resultado.resolved_selection ?? null
  );

// ==================================================
// DISPLAY FIELDS
// ==================================================

// Campos BASE da listagem.
//
// Eles aparecem sempre em query_shape = list.

const CAMPOS_BASE_LISTAGEM = [
  'ticket',
  'status',
  'created_on',
  'store_name',
  'category',
  'subcategory',
  'service_description',
];

// Campos extras permitidos na apresentação.

const DISPLAY_FIELDS_VALIDOS = [
  'praca',
  'analyst_responsible',
  'supplier',
  'requester',
  'completion_date',
  'visit_date',
];

function obterDisplayFields(
  state
) {
  if (
    !Array.isArray(
      state.display_fields
    )
  ) {
    return [];
  }

  return [
    ...new Set(
      state.display_fields.filter(
        campo =>
          typeof campo ===
            'string' &&
          DISPLAY_FIELDS_VALIDOS.includes(
            campo
          )
      )
    ),
  ];
}

const displayFields =
  obterDisplayFields(
    finalState
  );

let output = '';

// ==================================================
// COUNT
// ==================================================

if (queryShape === 'count') {
  const total =
    Number(
      rows?.[0]?.total ?? 0
    );

  output =
    montarFraseResumo(
      total,
      finalState
    );

  if (resumoSelecaoContextual) {
    output +=
      `\n\n${resumoSelecaoContextual}`;
  }
}


// ==================================================
// COMPARISON
// ==================================================

else if (
  queryShape === 'comparison'
) {
  output =
    montarRespostaComparacao(
      resultado.comparison ?? null,
      rows,
      finalState
    );

  if (resumoSelecaoContextual) {
    output +=
      `\n\n${resumoSelecaoContextual}`;
  }

  const detalhamentoComparacao =
    montarDetalhamentoComparacao(
      resultado.comparison ?? null,
      resultado.breakdown ?? null
    );

  if (detalhamentoComparacao) {
    output +=
      `\n\n${detalhamentoComparacao}`;
  }

  const analiseDrivers =
    montarAnaliseDrivers(
      resultado.comparison ?? null,
      resultado.driver_analysis ?? null
    );

  if (analiseDrivers) {
    output +=
      `\n\n${analiseDrivers}`;
  }

  // Mostra somente filtros comuns que ainda não
  // estejam evidentes no texto da comparação.
  const stateResumoComparacao = {
    ...finalState,
  };

  const dimensionComparada =
    resultado.comparison?.dimension ??
    finalState.comparison?.dimension ??
    null;

  if (dimensionComparada === 'period') {
    stateResumoComparacao.year = null;
    stateResumoComparacao.month = null;
    stateResumoComparacao.start_date = null;
    stateResumoComparacao.end_date = null;
  }

  if (
    dimensionComparada === 'praca' ||
    dimensionComparada === 'store_name' ||
    dimensionComparada === 'location_term'
  ) {
    stateResumoComparacao.praca = null;
    stateResumoComparacao.store_name = null;
    stateResumoComparacao.location_term = null;
  }

  if (
    dimensionComparada &&
    Object.prototype.hasOwnProperty.call(
      stateResumoComparacao,
      dimensionComparada
    )
  ) {
    stateResumoComparacao[dimensionComparada] = null;
  }

  // Um único status já aparece naturalmente em
  // "chamados em atendimento", "em aberto", etc.
  if (
    Array.isArray(stateResumoComparacao.statuses) &&
    stateResumoComparacao.statuses.length === 1
  ) {
    stateResumoComparacao.statuses = null;
  }

  const resumoComparacao =
    montarResumoFiltros(
      stateResumoComparacao
    );

  if (resumoComparacao) {
    output +=
      `\n\nConsiderei também: ${resumoComparacao}.`;
  }
}

// ==================================================
// LIST
// ==================================================

else if (
  queryShape === 'list'
) {
  if (rows.length === 0) {
    output =
      'Não há chamados que atendam aos filtros informados.';

    if (resumoFiltros) {
      output +=
        `\n\nConsiderei: ${resumoFiltros}.`;
    }

    if (resumoSelecaoContextual) {
      output +=
        `\n\n${resumoSelecaoContextual}`;
    }
  } else {
    output =
      montarFraseResumo(
        rowCount,
        finalState
      );

    if (resumoSelecaoContextual) {
      output +=
        `\n\n${resumoSelecaoContextual}`;
    }

    // -----------------------------------------------
    // TABELA — somente quando solicitada
    // -----------------------------------------------

    if (
      responseFormat === 'table'
    ) {
      output +=
        rowCount === 1
          ? '\n\nOrganizei o chamado em tabela, conforme solicitado:'
          : '\n\nOrganizei a listagem em tabela, conforme solicitado:';

      const camposTabela = [
        ...new Set([
          ...CAMPOS_BASE_LISTAGEM,
          ...displayFields,
        ]),
      ];

      const tabela =
        montarTabela(
          rows,
          camposTabela
        );

      if (tabela) {
        output +=
          `\n\n${tabela}`;
      }
    }

    // -----------------------------------------------
    // LISTA DETALHADA — padrão
    // -----------------------------------------------

    else {
      output +=
        rowCount === 1
          ? '\n\nAqui estão os detalhes do chamado:'
          : '\n\nAqui está a listagem dos chamados:';

      const lista =
        montarListaDetalhada(
          rows,
          displayFields
        );

      if (lista) {
        output +=
          `\n\n${lista}`;
      }
    }

    if (truncated) {
      output +=
        '\n\n> A consulta atingiu o limite de segurança de registros. Refine os filtros para visualizar um conjunto menor.';
    }
  }
}

// ==================================================
// GROUP
// ==================================================

else if (
  queryShape === 'group'
) {
  if (rows.length === 0) {
    output =
      'Não há dados para o agrupamento solicitado.';
  } else {
    const groupBy =
      finalState.group_by;

    output =
      `Aqui está a distribuição dos chamados por **${labelCampo(
        groupBy
      )}**:`;

    if (resumoFiltros) {
      output +=
        `\n\n${resumoFiltros}`;
    }

    if (resumoSelecaoContextual) {
      output +=
        `\n\n${resumoSelecaoContextual}`;
    }

    if (groupBy) {
      output +=
        `\n\n${montarTabela(
          rows,
          [
            groupBy,
            'total',
          ]
        )}`;
    }
  }
}

// ==================================================
// RANKING
// ==================================================

else if (
  queryShape === 'ranking'
) {
  if (rows.length === 0) {
    output =
      'Não há dados para o ranking solicitado.';
  } else {
    const groupBy =
      finalState.group_by;

    output =
      `Aqui está o ranking dos chamados por **${labelCampo(
        groupBy
      )}**:`;

    if (resumoFiltros) {
      output +=
        `\n\n${resumoFiltros}`;
    }

    if (resumoSelecaoContextual) {
      output +=
        `\n\n${resumoSelecaoContextual}`;
    }

    if (groupBy) {
      output +=
        `\n\n${montarTabela(
          rows,
          [
            groupBy,
            'total',
          ]
        )}`;
    }
  }
}

// ==================================================
// FALLBACK DE SEGURANÇA
// ==================================================

else {
  output =
    'A consulta foi executada, mas não foi possível identificar o formato da resposta.';
}

// ==================================================
// RESPOSTA PARA O FRONTEND
// ==================================================

const resposta = {
  output,
};

// ==================================================
// QA DEBUG
// ==================================================

if (isQa) {
  const interpretationNode =
    $('Interpretar Estado da Consulta')
      .first()
      .json;

  let interpretation =
    interpretationNode.output ??
    interpretationNode;

  if (
    typeof interpretation ===
    'string'
  ) {
    try {
      interpretation =
        JSON.parse(
          interpretation
        );
    } catch {
      // Mantém texto caso não seja
      // JSON válido.
    }
  }

  resposta.debug = {
    session_id:
      trigger.sessionId ??
      null,

    qa_run_id:
      trigger.qaRunId ??
      null,

    previous_state:
      $('Buscar Estado da Conversa')
        .first()
        .json ?? {},

    interpretation,

    final_state:
      finalState,

    response_format:
      responseFormat,

    display_fields:
      displayFields,

    structured_query: {
      success:
        resultado.success ??
        null,

      query_shape:
        resultado.query_shape ??
        null,

      row_count:
        resultado.row_count ??
        null,

      truncated:
        resultado.truncated ??
        false,

      columns:
        resultado.columns ??
        [],

      comparison:
        resultado.comparison ??
        null,

      breakdown:
        resultado.breakdown ??
        null,

      driver_analysis:
        resultado.driver_analysis ??
        null,

      resolved_selection:
        resultado.resolved_selection ??
        null,
    },
  };
}

// ==================================================
// RETORNO
// ==================================================

return [
  {
    json: resposta,
  },
];

parameters.jsonBody:
={{
  (() => {
    const s = $('Mesclar Estado da Consulta').first().json;

    const {
      session_id,
      intent,
      query_shape,
      response_format,
      comparison,
      selection_context,
      display_fields,
      ...state
    } = s;

    return {
      query_shape,
      comparison,
      selection_context,
      state
    };
  })()
}}
